-- Description: Current active relationship for LNK_PAYMASTER_EARNCODE using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: RELATIONSHIP_BASED_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_PAYMASTER_EARNCODE_HKEY AS LNK_PAYMASTER_EARNCODE_HKEY,
    l.PAYMASTER_HKEY AS PAYMASTER_HKEY,
    l.EARNCODE_HKEY AS EARNCODE_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls.DATELASTSYNC

    ROW_NUMBER() OVER (
        PARTITION BY l.PAYMASTER_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls.DATELASTSYNC
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_paymaster_earncode') }} l
INNER JOIN {{ ref('lks_bh1_paymaster_earncode_curr') }} ls
    ON l.LNK_PAYMASTER_EARNCODE_HKEY = ls.LNK_PAYMASTER_EARNCODE_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
